using System;
using System.Drawing;
using System.Windows.Forms;
namespace VinsPDF {
internal sealed class EditorPalette : DarkWindow {
 public event Action<string> Command;public bool AllowClose;bool loading;
 public readonly Button SelectButton,HandButton;public readonly CheckBox Highlight,Lines;
 readonly FlowLayoutPanel content=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(7)};
 readonly ComboBox family;readonly NumericUpDown size,line,paragraph,character,gridSpacing,gridAlpha,angle,margin;readonly CheckBox bold,italic,gridShow,gridSnap,allPages;readonly TextBox header,footer;readonly ComboBox alignment;readonly Panel fontSection;readonly TrackBar opacity;
 public double FloatingOpacity{get{return opacity.Value/100.0;}}
 public EditorPalette(){Text="EDIT";TopLevel=false;EmbeddedTitle(false);Resizable=false;Dock=DockStyle.Fill;Font=new Font("Segoe UI",9);Controls.Add(content);SelectButton=Add("Select / rectangle","select");HandButton=Add("Hand / pan","hand");Add("Add text","addtext");Add("Add image","image");Add("Edit text on page","edittext");
 fontSection=Section("Font / text",240);family=Combo(fontSection,PdfEngine.AvailableFamilies,8,8,198);size=Number(fontSection,"Size (pt)",14,1,500,42);bold=Check(fontSection,"Bold",8,78);italic=Check(fontSection,"Italic",110,78);var apply=Button("Apply text · Ctrl+Enter","fontapply");apply.SetBounds(8,112,198,28);fontSection.Controls.Add(apply);var cancel=Button("Cancel text · Esc","canceltext");cancel.SetBounds(8,144,198,28);fontSection.Controls.Add(cancel);fontSection.Controls.Add(new Label{Text="Type directly inside the page border.\nFont applies to the whole text item.",Left=8,Top=179,Width=200,Height=48,ForeColor=Color.Silver});
 var spacing=Section("Spacing",158);line=Number(spacing,"Line height",1.2m,.5m,5,8);paragraph=Number(spacing,"Paragraph pt",6,0,100,43);character=Number(spacing,"Character pt",0,-2,30,78);var spacingApply=Button("Apply spacing","spacingapply");spacingApply.SetBounds(8,116,198,28);spacing.Controls.Add(spacingApply);
 var rotate=Section("Rotate selection",82);angle=Number(rotate,"Degrees clockwise",90,-360,360,8);var rotateApply=Button("Rotate selection","rotateapply");rotateApply.SetBounds(8,44,198,28);rotate.Controls.Add(rotateApply);
 var grid=Section("Grid",145);gridShow=Check(grid,"Show grid",8,8);gridSnap=Check(grid,"Snap",118,8);gridSpacing=Number(grid,"Spacing mm",10,1,100,40);gridAlpha=Number(grid,"Visibility %",25,5,80,76);var gridApply=Button("Apply grid","gridapply");gridApply.SetBounds(8,109,198,28);grid.Controls.Add(gridApply);
 var hf=Section("Header / footer",260);header=TextInput(hf,"",8,26);footer=TextInput(hf,"Page {page} of {pages}",8,78);hf.Controls.Add(new Label{Text="Header",Left=8,Top=5,ForeColor=Color.Silver});hf.Controls.Add(new Label{Text="Footer",Left=8,Top=57,ForeColor=Color.Silver});allPages=Check(hf,"All pages",8,108);alignment=Combo(hf,new[]{"Left","Centre","Right"},8,140,198);alignment.SelectedIndex=1;margin=Number(hf,"Margin mm",12,3,50,174);var hfApply=Button("Add header / footer","headerapply");hfApply.SetBounds(8,214,198,28);hf.Controls.Add(hfApply);
 Add("Delete selection","delete");Add("Undo","undo");Add("Redo","redo");Highlight=new CheckBox{Text="Border editable items",Checked=true,Width=210,Height=24,ForeColor=Color.Silver};Lines=new CheckBox{Text="Recognise text lines",Checked=true,Width=210,Height=24,ForeColor=Color.Silver};content.Controls.Add(Highlight);content.Controls.Add(Lines);var panel=Section("Panel position / opacity",116);var floating=Button("Float / dock panel","float");floating.SetBounds(8,8,198,28);panel.Controls.Add(floating);panel.Controls.Add(new Label{Text="Floating panel opacity",Left=8,Top=43,Width=198,ForeColor=Color.Silver});opacity=new TrackBar{Minimum=40,Maximum=100,Value=92,TickStyle=TickStyle.None,Left=8,Top=68,Width=198,Height=28,AutoSize=false};panel.Controls.Add(opacity);opacity.ValueChanged+=delegate{if(TopLevel)Opacity=FloatingOpacity;};InstallTitle();HideMinMax();EmbeddedTitle(false);FormClosing+=delegate(object sender,FormClosingEventArgs e){if(TopLevel&&!AllowClose&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Send("close");}};
 family.SelectedIndexChanged+=StyleEdited;size.ValueChanged+=StyleEdited;bold.CheckedChanged+=StyleEdited;italic.CheckedChanged+=StyleEdited;line.ValueChanged+=StyleEdited;paragraph.ValueChanged+=StyleEdited;character.ValueChanged+=StyleEdited;
 }
 void StyleEdited(object s,EventArgs e){if(!loading)Send("stylepreview");}
 void Send(string command){if(Command!=null)Command(command);}
 Button Button(string text,string command){var b=new Button{Text=text,Width=214,Height=28,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(18,18,18),ForeColor=Color.White,Margin=new Padding(0,1,0,1)};b.FlatAppearance.BorderColor=Color.FromArgb(65,65,65);b.Click+=delegate{Send(command);};return b;}
 Button Add(string text,string command){var b=Button(text,command);content.Controls.Add(b);return b;}
 Panel Section(string text,int height){var b=Button("+ "+text,"");var p=new Panel{Width=214,Height=height,Visible=false,BackColor=Color.FromArgb(12,12,12),Margin=new Padding(0)};b.Click+=delegate{p.Visible=!p.Visible;b.Text=(p.Visible?"− ":"+ ")+text;};content.Controls.Add(b);content.Controls.Add(p);return p;}
 NumericUpDown Number(Control parent,string label,decimal value,decimal min,decimal max,int y){parent.Controls.Add(new Label{Text=label,Left=8,Top=y+4,Width=118,ForeColor=Color.Silver});var n=new NumericUpDown{Left=130,Top=y,Width=76,DecimalPlaces=1,Minimum=min,Maximum=max,Value=value,BackColor=Color.FromArgb(25,25,25),ForeColor=Color.White};parent.Controls.Add(n);return n;}
 CheckBox Check(Control parent,string label,int x,int y){var c=new CheckBox{Text=label,Left=x,Top=y,Width=100,Height=26,ForeColor=Color.Silver};parent.Controls.Add(c);return c;}
 ComboBox Combo(Control parent,string[] items,int x,int y,int width){var c=new ComboBox{Left=x,Top=y,Width=width,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Color.FromArgb(25,25,25),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};c.DrawMode=DrawMode.OwnerDrawFixed;c.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(var brush=new SolidBrush(Color.FromArgb(25,25,25)))e.Graphics.FillRectangle(brush,e.Bounds);int index=e.Index<0?c.SelectedIndex:e.Index;if(index>=0)TextRenderer.DrawText(e.Graphics,c.Items[index].ToString(),c.Font,e.Bounds,Color.White,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};c.Items.AddRange(items);if(items.Length>0)c.SelectedIndex=0;parent.Controls.Add(c);return c;}
 TextBox TextInput(Control parent,string value,int x,int y){var t=new TextBox{Text=value,Left=x,Top=y,Width=198,BackColor=Color.FromArgb(25,25,25),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};parent.Controls.Add(t);return t;}
 public TextStyle Style{get{return new TextStyle{Family=family.Text,Size=(float)size.Value,Bold=bold.Checked,Italic=italic.Checked,LineHeight=(float)line.Value,ParagraphGap=(float)paragraph.Value,CharacterSpacing=(float)character.Value};}}
 public void SetStyle(TextStyle style){loading=true;family.SelectedItem=style.Family;size.Value=(decimal)Math.Max(1,Math.Min(500,style.Size));bold.Checked=style.Bold;italic.Checked=style.Italic;line.Value=(decimal)style.LineHeight;paragraph.Value=(decimal)style.ParagraphGap;character.Value=(decimal)style.CharacterSpacing;loading=false;}
 public void ExpandFont(){fontSection.Visible=true;foreach(Control c in content.Controls)if(c is Button&&c.Text.EndsWith("Font / text"))c.Text="− Font / text";content.ScrollControlIntoView(fontSection);}
 public float Rotation{get{return(float)angle.Value;}}public string Header{get{return header.Text;}}public string Footer{get{return footer.Text;}}public bool AllPages{get{return allPages.Checked;}}public int Alignment{get{return alignment.SelectedIndex;}}public float MarginMm{get{return(float)margin.Value;}}
 public void ApplyGrid(PageCanvas canvas){canvas.GridVisible=gridShow.Checked;canvas.SnapGrid=gridSnap.Checked;canvas.GridMm=(float)gridSpacing.Value;canvas.GridAlpha=(int)(gridAlpha.Value*255/100);canvas.Invalidate();}
 public void Mode(bool select){SelectButton.BackColor=select?Color.FromArgb(40,70,95):Color.FromArgb(18,18,18);HandButton.BackColor=!select?Color.FromArgb(40,70,95):Color.FromArgb(18,18,18);}
 public void SetBusy(bool busy){content.Enabled=!busy;}
}
}
